  onSelectAfter:()=>{const list=cardInstances.filter(a=>a.element.isConnected).sort((a,b)=>{const x=engine.card(a.element.dataset.cardUid),y=engine.card(b.element.dataset.cardUid),pos=c=>c.bagPos<1?2147483647:c.bagPos;return pos(x)-pos(y)||x.id-y.id||Number(String(x.uid).replace(/^c/,''))-Number(String(y.uid).replace(/^c/,''));});const first=list[0];if(first){first.interaction?.select(true);first.element.focus({preventScroll:true});}else for(const rite of engine.state.rites){const a=riteInstances.find(a=>a.element.dataset.riteUid===rite.uid&&a.element.isConnected);if(a){a.element.focus({preventScroll:true});break;}}},
